varying highp vec2 textureCoordinate;

    uniform sampler2D inputTexture;
    uniform sampler2D effectTexture;
    uniform sampler2D maskTexture;

    uniform highp float alpha;

    void main() {
        vec4 inputColor = texture2D(inputTexture, textureCoordinate);
        vec4 effectColor = texture2D(effectTexture, textureCoordinate);
        vec4 maskColor = texture2D(maskTexture, textureCoordinate);

        if (maskColor.r > 0.001) {
            gl_FragColor = mix(inputColor, effectColor, effectColor.a * alpha * maskColor.r);
        } else {
            gl_FragColor = inputColor;
        }
    }

