varying highp vec2 vCoords;
    uniform sampler2D uInput;
#ifdef MASK
    uniform sampler2D uInput1;
#endif
    uniform vec4 mean;
    uniform vec4 norm;
    uniform vec4 flag;

    void main() {
        vec4 color = texture2D(uInput, vCoords);
    #ifdef MASK
        color.w = texture2D(uInput1, vCoords).y;
    #endif
        color = mix(color, color.bgra, flag.x);
        color = mix(color, vec4(color.r, color.r, color.r, 0), flag.y);
        color = mix(color, vec4(color.g), flag.z);
        gl_FragColor    = (color - mean) * norm;
    }

